export type GetPaymentIntentResult = { /** Itemized invoice, subscription, and automatic tax fees collected with this payment. Available to the merchant only. Empty until fees settle or when no add-ons apply. Refunds do not return or revise these fees. */ "add_on_fees"?: Array<PaymentAddOnFee>; "amount_money": MoneyValue; /** RFC3339 timestamp. Format: date-time. */ "authorization_expires_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "authorized_at"?: string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "authorized_money"?: MoneyValue; /** Flint-normalized reason the payment intent was canceled. Unknown processor values are returned as payment_canceled. */ "cancellation_reason"?: "requested_by_customer" | "duplicate" | "fraudulent" | "abandoned" | "authorization_expired" | "invoice_payment_failed" | "invoice_voided" | "payment_canceled" | (string & {}); /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "capturable_money"?: MoneyValue; "capture_method"?: "automatic" | "manual" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "captured_at"?: string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "captured_money"?: MoneyValue; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; /** Typed browser authority for the current standalone payment action. Complete it, then call the same confirm endpoint without a replacement credential. Absent when no browser action is required. */ "current_payment_action"?: PendingPaymentAction; "customer"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id": string; "email": string; "name"?: string; "phone"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "customer_id"?: string; "dispute_status"?: "none" | "warning_needs_response" | "warning_under_review" | "warning_closed" | "needs_response" | "under_review" | "won" | "lost" | "prevented" | (string & {}); /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_hold"?: PaymentFulfillmentHold; "invoice"?: (({ "collection_block_status"?: "none" | "inventory_blocked" | "resolved" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; /** RFC3339 timestamp. Format: date-time. */ "due_at"?: string; "invoice_id": string; "invoice_number"?: string; "is_overdue": boolean; "order_id"?: string; "outstanding_money": MoneyValue; "paid_money": MoneyValue; "refund_status"?: "none" | "partially_refunded" | "refunded" | (string & {}); "refunded_money": MoneyValue; "status": "draft" | "open" | "partially_paid" | "paid" | "void" | "uncollectible" | "credited" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "invoice_id"?: string; "last_payment_error"?: (({ /** Flint-normalized payment failure code. Unknown provider values are returned as payment_failed. */ "code": "card_declined" | "insufficient_funds" | "bank_account_closed" | "bank_account_not_found" | "bank_debit_not_authorized" | "bank_account_restricted" | "bank_debit_limit_exceeded" | "authentication_required" | "payment_blocked" | "expired_card" | "incorrect_cvc" | "processing_error" | "payment_method_unavailable" | "payment_method_declined" | "payment_not_completed" | "payment_action_expired" | "payment_method_temporarily_unavailable" | "payment_failed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "failed_at"?: string; /** Flint-authored merchant-facing payment failure message. This is stable explanatory text, not raw provider copy. */ "message": string; "remediation"?: ErrorRemediation; }) | (null)); "merchant_id"?: string; /** Captured amount minus processing_fee_money and every amount in add_on_fees. Later merchant assessments and credits are separate balance effects. */ "merchant_net_money"?: MoneyValue; "metadata"?: Record<string, string>; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed" | (string & {}); "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid" | (string & {}); "pricing_amounts": PricingAmounts; "refund_status": "none" | "partially_refunded" | "refunded" | (string & {}); "settlement_amounts": SettlementAmounts; "status": "open" | "closed" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; }) | (null)); "order_id"?: string; "origin"?: "virtual_terminal" | "payment_link" | "checkout" | "api" | "subscription" | (string & {}); "payment_collection"?: PaymentCollection; "payment_flow": "checkout" | "payment_link" | "invoice" | "subscription_initial" | "subscription_renewal" | "virtual_terminal" | "api" | (string & {}); "payment_intent_id": string; "payment_options": Array<"card" | "apple_pay" | "google_pay" | "affirm" | "ach_debit" | (string & {})>; "payment_source"?: PaymentSourceSummary; /** Flint's all-in processing fee for this payment. It is the complete price Flint charges to process the payment, never a provider cost passed through. The fee is final once the card payment is captured or the ACH payment succeeds; canceled payments and failures before success have none. Invoice, subscription, and automatic tax fees are itemized separately in add_on_fees. Your net for the payment is captured_money minus this fee and the add-on fees. Refunds do not return or revise it. */ "processing_fee_money"?: MoneyValue; "receipt_email"?: string; "refund_status"?: "none" | "partially_refunded" | "refunded" | (string & {}); /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "refunded_money"?: MoneyValue; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "released_money"?: MoneyValue; "risk"?: (({ /** RFC3339 timestamp. Format: date-time. */ "evaluated_at": string; "level": "normal" | "elevated" | "highest" | "not_assessed" | (string & {}); "matched_risk_rule_id"?: string; "outcome"?: "authorized" | "manual_review" | "blocked" | "issuer_declined" | "invalid" | null | (string & {}) | null; "outcome_reason"?: "highest_risk" | "elevated_risk" | "low_authorization_probability" | "risk_rule" | "risk_policy" | null | (string & {}) | null; "review_id"?: string; /** Format: int32. */ "score"?: number; "statement": string; }) | (null)); "selected_payment_option"?: string; "settlement_status"?: "none" | "partially_refunded" | "refunded" | "disputed" | (string & {}); "status": "requires_payment_method" | "requires_confirmation" | "requires_action" | "processing" | "requires_capture" | "canceled" | "succeeded" | "expired" | (string & {}); /** Opaque payment reference to share with merchant support. Do not parse its format. */ "support_reference": string; "tip_money"?: MoneyValue; "transaction_purpose"?: "goods" | "services" | "other" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string; };
